import { test, expect } from '@playwright/test';

test.describe('JavaScript Confirm Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
  });

  test('Accepting the confirm dialog', async ({ page }) => {
    await page.getByText('Click for JS Confirm').click();
    const [dialog] = await Promise.all([
      page.waitForEvent('dialog'),
      page.getByText('Click for JS Confirm').click(),
    ]);
    await dialog.accept();
    const resultText = await page.getByText('#result');
    expect(await resultText.innerText()).toBe('You clicked: Ok');
  });

  test('Dismissing the confirm dialog', async ({ page }) => {
    await page.getByText('Click for JS Confirm').click();
    const [dialog] = await Promise.all([
      page.waitForEvent('dialog'),
      page.getByText('Click for JS Confirm').click(),
    ]);
    await dialog.dismiss();
    const resultText = await page.getByText('#result');
    expect(await resultText.innerText()).toBe('You clicked: Cancel');
  });
});
